"""Build static customer-journey pages from the supplied Tony page briefs."""
from pathlib import Path
from html import escape as esc
import re
ROOT=Path(__file__).resolve().parent.parent
home=(ROOT/'index.html').read_text()
svg=re.search(r'  <svg class="svg-library".*?</svg>',home,re.S)[0]
header=re.search(r'  <header.*?</header>',home,re.S)[0]
footer=re.search(r'  <footer.*?</footer>',home,re.S)[0]
ARROW='<svg aria-hidden="true"><use href="#i-arrow"/></svg>'
NAV=[('index.html','Home'),('what-we-solve.html','What We Solve'),('who-we-help.html','Who We Help'),('how-it-works.html','How It Works'),('results.html','Results'),('about.html','About'),('resources.html','Resources'),('lets-talk.html',"Let's Talk")]
def link(url,text,button=False):return f'<a class="{"button button-primary" if button else "text-link"}" href="{url}">{text} {ARROW}</a>'
def image(name,alt,lazy=True):return f'<img src="assets/images/{name}.webp" width="1600" height="1067" {"loading=\"lazy\"" if lazy else "fetchpriority=\"high\""} alt="{esc(alt,quote=True)}">'
def heading(ey,title,copy=''):
 if '<br>' in title:
  first, last=title.rsplit('<br>',1);title=first+'<br><em>'+last+'</em>'
 return f'<div class="section-heading"><p class="eyebrow">{ey}</p><h2>{title}</h2>{f"<p>{copy}</p>" if copy else ""}</div>'
def section(content,tone='',id=''):return f'<section class="page-section {tone}"{f" id=\"{id}\"" if id else ""}><div class="container">{content}</div></section>'
def hero(num,title,desc,img,alt,cta,href='#page-content',label=None):
 return f'<section class="page-hero" id="page-top">{image(img,alt,False)}<div class="container"><div class="page-hero-content"><p class="eyebrow">{label or NAV[num-1][1]}</p><h1>{title}</h1><p>{desc}</p><div class="hero-actions">{link(href,cta,True)}</div></div></div><span class="page-number">{num:02} / 08 · ONE CONTINUOUS CUSTOMER JOURNEY</span></section>'
def symbol(name):return f'<svg aria-hidden="true"><use href="#{name}"/></svg>'
def card_icon(title):
 text=title.lower()
 for word, icon in [('situation','chat'),('sense','eye'),('priorities','admin'),('time','clock'),('response','chat'),('inquir','phone'),('opportun','leads'),('customer','chat'),('system','systems'),('capacity','users'),('people','users'),('visibility','eye'),('understand','eye'),('context','eye'),('plan','admin'),('administr','admin'),('handoff','flow'),('friction','flow'),('coordinate','flow'),('overload','owner'),('accountab','check')]:
  if word in text:return 'i-'+icon
 return 'i-check'
def cards(items, photos=None):
 result='<div class="insight-grid'+(' photo-insights' if photos else '')+'">'
 for i,(title,copy) in enumerate(items):
  photo=image(*photos[i]) if photos else ''
  result+=f'<article class="insight-card">{photo}<div class="insight-copy"><span class="insight-symbol">{symbol(card_icon(title))}</span><h3>{title}</h3><p>{copy}</p></div></article>'
 return result+'</div>'
def symptoms(items):
 return '<div class="symptom-layout"><figure class="symptom-photo">'+image('symptom-working-day','A neighborhood food-truck team serving customers during a busy day')+'<figcaption>The work keeps moving.<br><span>So should your support.</span></figcaption></figure>'+cards(items)+'</div>'
def rhythm():
 items=[('Plan','i-admin','Agree the priorities.'),('Execute','i-check','Put the support to work.'),('Review','i-eye','See what is changing.'),('Adjust','i-flow','Improve the next step.')]
 return section(heading('An operating rhythm','Progress Is a Rhythm.<br>Keep Learning as You Go.','A practical cycle of clear priorities, action, and review—shaped around how your business works.')+'<ol class="operating-rhythm">'+''.join(f'<li><span>{symbol(icon)}</span><h3>{title}</h3><p>{copy}</p></li>' for title,icon,copy in items)+'</ol>','soft')
def heartland_history():
 return section('<div class="heartland-feature"><div class="heartland-story"><p class="eyebrow">A chapter in the journey · Heartland</p><h2>Experience in Payments.<br><em>Perspective for the Business.</em></h2><p>Tony’s time at Heartland adds a payments-industry chapter to his experience across customer-facing businesses and operational teams.</p><p>This record from his personal archive connects that chapter to the broader perspective behind One Mahogany Global.</p><span class="heartland-archive-label">'+symbol('i-admin')+'From Tony’s career archive</span></div><div class="heartland-board"><div class="heartland-board-heading"><span class="heartland-company">Heartland</span><span class="heartland-record-label">Career record</span></div><h3>Payments Leaderboard</h3><p class="heartland-board-note">Anthony Blanco · Selected fields from the supplied record</p><div class="heartland-table-wrap"><table class="heartland-table"><caption class="sr-only">Selected career-history fields from Tony’s Heartland payments leaderboard</caption><thead><tr><th scope="col">Rep name</th><th scope="col">Region</th><th scope="col">Division</th><th scope="col">Role</th></tr></thead><tbody><tr><th scope="row" data-label="Rep name">Anthony Blanco</th><td data-label="Region">Evergreen</td><td data-label="Division">CA13</td><td data-label="Role">RM</td></tr></tbody></table></div><div class="heartland-record-line" aria-hidden="true"><span></span></div><p class="heartland-source-note">Recreated from Tony’s supplied archive. Reporting period not shown in the original.</p><button class="heartland-source-trigger" type="button" data-record-open="heartland-document" aria-haspopup="dialog"><span class="heartland-document-icon">'+symbol('i-admin')+'</span><span class="heartland-document-label"><strong>View original record</strong><span>Open the Heartland document</span></span><svg class="heartland-expand-icon" viewBox="0 0 24 24" aria-hidden="true"><path d="M8 3H3v5m13-5h5v5M3 16v5h5m13-5v5h-5"/></svg></button><dialog class="heartland-document-dialog" id="heartland-document" aria-labelledby="heartland-document-title"><div class="heartland-document-toolbar"><h2 id="heartland-document-title">Original Heartland leaderboard</h2><button type="button" class="heartland-document-close" data-record-close aria-label="Close document preview">'+symbol('i-close')+'</button></div><figure><img src="assets/images/tony-heartland-leaderboard.webp" width="960" height="462" loading="lazy" alt="Original supplied Heartland payments and payroll leaderboard screenshot, including Anthony Blanco’s row"><figcaption>From Tony’s career archive. Reporting period not shown in the original.</figcaption></figure></dialog></div></div>','soft',id='heartland-history')
def brandfilm():
 return section('<div class="brand-film-layout"><div class="brand-film-copy"><p class="eyebrow">The bigger picture</p><h2>Stronger businesses.<br><em>Brighter communities.</em></h2><p>Behind the everyday work are people, families, and communities. That is why the right support matters.</p><p class="film-duration">One Mahogany Global · 15-second brand film</p></div><figure class="brand-film"><video controls playsinline preload="none" poster="assets/images/brand-film-poster.webp" aria-label="One Mahogany Global brand film" aria-describedby="brand-film-caption"><source src="assets/video/hero.mp4" type="video/mp4"><track kind="captions" src="assets/video/brand-film.vtt" srclang="en" label="English">Your browser does not support video. The film celebrates community, support, freedom, and family.</video><figcaption id="brand-film-caption">Community. Support. Freedom. Family. A short film about the people behind the business.</figcaption></figure></div>','soft')
def split(ey,title,paras,img,alt,reverse=False,cta=None):
 photo_class=' tony-office-scene' if img=='tony-ceo-office' else ''
 return f'<div class="story-split {"image-right" if reverse else ""}"><figure class="story-photo{photo_class}">{image(img,alt)}</figure><div class="story-copy"><p class="eyebrow">{ey}</p><h2>{title}</h2>'+''.join(f'<p>{p}</p>' for p in paras)+(link(*cta) if cta else '')+'</div></div>'
def framework():
 return section(heading('The connected framework','People Do the Work.<br>Systems Support It. Process Connects It.','A business problem rarely sits in one place. We look at the whole path the work takes.')+'<div class="framework"><article><h3>People</h3><p>The capacity, skills, clarity, and accountability around the work. Who owns the next step, and do they have what they need?</p></article><article><h3>Business Systems</h3><p>The tools, information, technology, and operating infrastructure that support people. Do they connect, and do they make work easier?</p></article><article><h3>Process</h3><p>The way work moves from one person or decision to the next. Clear handoffs, follow-up, standards, and ownership.</p></article></div><p class="framework-note">Technology and AI can support the work where appropriate. They belong inside the solution, guided by the people and process around them.</p>','dark')
def capabilities():
 return section(heading('Capabilities follow the problem','The Support Fits the Work.','You do not have to choose a service. Once the problem is understood, the solution can draw on either or both of these capability families.')+'<div class="capability-pair"><article><h3>Voice-Enabled Support</h3><p>When customers need someone to answer, explain, schedule, or follow through.</p><ul><li>Customer service and answering service</li><li>Technical support and appointment setting</li><li>Lead generation and outbound support</li><li>Virtual assistance — voice</li></ul></article><article><h3>Non-Voice Support</h3><p>When messages, information, and back-office work need dependable ownership.</p><ul><li>Chat, email, and social media support</li><li>Virtual assistance — non-voice</li><li>Data entry and transcription</li><li>Back-office administration</li></ul></article></div>')
OUTCOMES=[('More Time','Less routine work competing for the owner’s attention. More room for decisions that need your experience.'),('Better Response','Customers, leads, and internal requests receive consistent attention without everything depending on one person.'),('Less Friction','Fewer unnecessary handoffs, repeated tasks, delays, and moments of confusion.'),('More Visibility','A clearer view of what is happening, who owns it, and what needs attention next.'),('Greater Capacity','The ability to handle more work without every additional responsibility landing on you.'),('More Consistency','Repeatable ways of working that rely on clear ownership, rather than memory or improvisation.')]
def outcomes():return section(heading('Business improvement','What Better Can Look Like.','These are the outcomes we work toward. The priorities and measures depend on your business.')+cards(OUTCOMES),'soft')
def nextpage(current,title,copy,cta):
 nxt=NAV[current];prev=NAV[current-2]
 return f'<section class="page-section next-chapter"><div class="container"><p class="eyebrow">The next chapter · {nxt[1]}</p><h2>{title}</h2><p>{copy}</p>{link(nxt[0],cta,True)}{link("lets-talk.html","Or tell us what’s happening") if current<7 else ""}<a class="journey-back" href="{prev[0]}">Previous chapter: {prev[1]}</a></div></section>'
# Deliberate page-specific photography; keep homepage and chapter imagery distinct.
PAGE_IMAGES = {
 'what-we-solve.html': {
  'contractor-call': ('solve-workshop', 'A craftsperson concentrating on work at a workshop bench'),
  'owner-laptop': ('solve-connected-work', 'An overhead view of the connected activity inside a neighborhood café'),
  'customer-conversation': ('solve-concierge', 'A shopkeeper greeting a customer across the counter of a neighborhood store')},
 'who-we-help.html': {
  'mechanic-shop': ('industry-auto-service', 'An overhead view of an automotive service workshop'),
  'contractor-900': ('industry-construction', 'A tradesperson working on the roof structure of a house'),
  'restaurant-900': ('industry-hospitality', 'A chef plating food in a restaurant kitchen'),
  'retail': ('industry-retail-team', 'A local shop team helping customers at the counter'),
  'home-services-900': ('industry-home-building', 'A tradesperson working on the timber frame of a house'),
  'barber-900': ('industry-personal-care', 'A barber carefully working with a customer'),
  'resources-worksite': ('industry-site-team', 'A road construction crew coordinating work around equipment')},
 'how-it-works.html': {'business-systems-900': ('method-organized-work', 'An organized service workspace with storage and a working counter')},
 'results.html': {'kitchen-team': ('results-service', 'Restaurant staff delivering prepared food during service')},
 'about.html': {
  'craftsperson-900': ('about-florist', 'A florist preparing an arrangement in a flower shop'),
  'tony-avaya-480': ('tony-bpo-office', 'A supplied archival photograph of Tony inside a business office')},
 'resources.html': {
  'resources-worksite': ('resource-market-team', 'A market team coordinating work around a produce stall'),
  'owner-laptop': ('resource-owner-admin', 'A business owner working at a laptop beside flowers and paperwork'),
  'business-systems-900': ('resource-digital-work', 'A person using a computer in a practical business workspace'),
  'collaboration': ('resource-teamwork', 'Colleagues discussing work around a table in a café')}
}
def write(filename,title,desc,content,active=None):
 for old, (new, alt) in PAGE_IMAGES.get(filename, {}).items():
  content=re.sub(r'<img\b[^>]*src="assets/images/'+re.escape(old)+r'\.webp"[^>]*>', lambda match: image(new, alt, 'loading="lazy"' in match.group(0)), content)
 h=header.replace('href="#home"','href="index.html"').replace(' aria-current="page"','')
 active=active or filename
 if active!='index.html':h=h.replace('class="nav-home"','class="nav-home-link"')
 if active!='index.html':h=h.replace(f'href="{active}"',f'href="{active}" aria-current="page"')
 f=footer.replace('href="#home" aria-label="One Mahogany Global home"','href="index.html" aria-label="One Mahogany Global home"').replace('href="#home" aria-label="Back to top"','href="#page-top" aria-label="Back to top"')
 page=f'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#358AD2"><meta name="robots" content="noindex,nofollow"><title>{esc(title)} — One Mahogany Global</title><meta name="description" content="{esc(desc,quote=True)}"><link rel="icon" href="assets/brand/icon.png"><link rel="preload" href="assets/fonts/poppins-regular.ttf" as="font" type="font/ttf" crossorigin><link rel="stylesheet" href="styles.css?v=journey-47"><link rel="stylesheet" href="modern.css?v=journey-47"><link rel="stylesheet" href="design-system.css?v=journey-47"><link rel="stylesheet" href="refresh.css?v=journey-47"><link rel="stylesheet" href="pages.css?v=journey-47"><script src="header-nav.js?v=3" defer></script><script src="site.js?v=journey-47" defer></script></head>
<body class="inner-page"><a class="skip-link" href="#main">Skip to content</a>{svg}{h}<div class="site-frame"><main id="main">{content}</main>{f}</div><noscript><p class="noscript-note">Email <a href="mailto:info@onemahogany.com">info@onemahogany.com</a> to start a conversation. Resource filters and email draft preparation require JavaScript.</p></noscript></body></html>'''
 (ROOT/filename).write_text(page)

# 02 — Recognize symptoms, look beneath them, then establish relevance.
s=hero(2,"Let's Look Underneath.","Missed calls. Slow follow-up. Overloaded staff. The problems you notice every day may only be the symptoms. What's getting in the way of the business working the way it should?",'contractor-call','A contractor handling a phone call beside a work van','Start with the symptoms')
s+=section(heading('The symptoms are clues','Sound Familiar?','These may look like separate problems. Often, they share the same underlying pressure.')+symptoms([('Missed Opportunities','Calls, inquiries, and leads fall through while the team is busy with the work already in front of them.'),('Owner Overload','Decisions, tasks, and exceptions keep coming back to one person, even when the business has a team.'),('Administrative Drag','Routine work takes time away from customers, planning, and the decisions that move the business forward.'),('Disconnected Systems','Information sits in inboxes, spreadsheets, messages, and people’s heads. Finding the complete picture takes work.'),('Inconsistent Follow-Through','The next step changes depending on who is handling it. Important work relies on someone remembering.'),('Limited Capacity','There is demand, but the business cannot absorb more work without adding pressure to the owner.')]),id='page-content')
s+=section(split('The problem behind the problem',"The Problem Isn't Always<br>Where It Shows Up.",['A missed call can look like a phone problem. It may actually be a question of capacity, ownership, or what happens after the call.','A delayed estimate can look like an employee problem. It may be a handoff problem. A lost lead can look like a marketing problem when follow-up has no clear home.','We trace the work before recommending the fix.'],'owner-laptop','A business owner reviewing work on a laptop'),'soft')
s+=framework()
s+=section(split('Business Concierge','You Bring the Problem.<br>We Help Coordinate the Moving Parts.',['You do not need to know whether the answer is another person, a better workflow, a connected system, or a different way to follow up.','One place to start. The right support from there. We help identify what deserves attention and coordinate the appropriate capabilities around it.'],'customer-conversation','An owner talking with a customer at the counter',True,('how-it-works.html','See how the support comes together')))
s+=capabilities()
s+=outcomes()
s+=nextpage(2,'Different Businesses.<br>Same Responsibility.','Your operating reality matters. A contractor, retailer, or restaurant owner may need a different combination of support. Does this approach fit a business like yours?','See who we help')
write('what-we-solve.html','What We Solve','Look beneath missed calls, owner overload, and disconnected systems to understand the operational problem.',s)

# 03 — Show real working environments and different combinations of support.
s=hero(3,'Different Businesses.<br>Same Responsibility.','Customers need you. Employees depend on you. Work needs to move. The business may look different from the outside, but the responsibility feels familiar.','counter-customer','A neighborhood shopkeeper helping a customer at the counter','Find your business in the story')
mosaic=[('mechanic-shop','Automotive & Repair','Customer updates, job handoffs, and the next repair waiting.','A mechanic working at a tool bench in a repair shop'),('contractor-900','Construction & Trades','Estimates, scheduling, and customers waiting for an update.','A construction professional coordinating work by phone'),('restaurant-900','Restaurants & Hospitality','Service, staffing, and the details behind every customer visit.','A cook preparing food during service'),('retail','Retail & Local Shops','Customers at the counter. Orders and administration behind it.','Customers shopping in a local store'),('home-services-900','Home Services','Keeping the work moving from inquiry to completed job.','A tradesperson carrying out work on a house roof'),('barber-900','Personal Services','Appointments, customer relationships, and hands-on work.','A barber cutting a customer’s hair'),('resources-worksite','Owner-Led Businesses','Different work. The same need for dependable support.','Workers coordinating activity on a construction site')]
s+=section(heading('America goes to work','People Like You.<br>Work Like Yours.','The industry label is only the beginning. What matters is what is happening inside your business.')+'<div class="photo-mosaic">'+''.join(f'<figure>{image(img,alt)}<figcaption><strong>{t}</strong><span>{c}</span></figcaption></figure>' for img,t,c,alt in mosaic)+'</div>',id='page-content')
s+=section(heading('Different businesses. Familiar problems.',"The Problem Isn't You.",'Often, the business has simply grown beyond what one owner or one small team can comfortably coordinate alone.')+cards([('A Contractor','You are on a job while the next customer calls. Lead follow-up and scheduling need a reliable path.'),('A Restaurant Owner','Service is moving, but messages and administrative tasks still wait until the end of your day.'),('A Retail Owner','The shop is busy. Stock information, customer inquiries, and back-office work need to stay connected.'),('A Service Business','Demand is growing. Handoffs, appointments, and customer updates need clear ownership.'),('A Professional Practice','Client work needs your experience. Repeated administrative work needs dependable capacity around it.'),('A Growing Team','More people are doing the work. Information, responsibilities, and processes need to grow with them.')]),'soft')
s+=section(split('The business behind the industry',"We Don't Start With Your Industry.<br>We Start With What's Happening.",['Not every contractor needs the same package. Not every restaurant has the same bottleneck.','You bring the context: your customers, your priorities, what works, and what keeps getting in the way. We help make sense of the moving parts.'],'workshop-doorway','An owner working in a workshop doorway'))
s+=framework()
s+=capabilities()
s+=section(split('The person behind the business','More Room for the Work.<br>And the Life Around It.',['You built something that matters to customers, employees, families, and your community. That responsibility deserves support.','The aim is a business that is easier to operate, with more clarity and less work depending entirely on you.'],'worksite-lead','A site lead beside a pickup truck on a construction site',True))
s+=nextpage(3,'So How Would This Work<br>for Your Business?','There is no universal package. The next step is understanding how the right combination of support takes shape around your priorities.','See how it works')
write('who-we-help.html','Who We Help','Support built around the operating realities of owner-led businesses, trades, restaurants, retail, and local services.',s)

# 04 — Explain delivery without putting the diagnostic burden on the owner.
s=hero(4,"We Don't Start With a Service.<br>We Start With Your Business.",'Tell us what is getting in the way. Before recommending people, systems, technology, or processes, we first need to understand what is happening inside yours.','collaboration','People reviewing work and notes together around a table','See the approach')
s+=section(heading('The Business Concierge','One Place to Start.<br>The Right Support From There.','You know the symptoms. You should not have to diagnose every operational cause alone.')+cards([('You Bring the Situation','The missed call. The task that keeps coming back. The work your team no longer has room to manage.'),('We Help Make Sense of It','We look at what happens around the problem, what is already working, and where the work gets stuck.'),('Together, We Set Priorities','We discuss what needs attention first, what support could help, and what a sensible next step would involve.')], [('concierge-listen','Two people talking inside a neighborhood barbershop'),('concierge-review','A tradesperson reviewing the work with a customer'),('concierge-plan','Two mechanics discussing a vehicle in their workshop')]),id='page-content')
s+=section(heading('The OMG method','Diagnose. Build. Operate.','A straightforward operating arc, shaped around your business.')+'''<ol class="method-steps"><li><figure><img src="assets/images/method-listen.webp" width="1600" height="1067" loading="lazy" alt="A store team discussing work at the service counter"></figure><div class="method-body"><span>01 · Diagnose</span><h3>Start With What's Happening.</h3><p>Listen before prescribing. Understand the pressure, customer experience, responsibilities, workload, and systems around the problem.</p><ul><li>What is working?</li><li>Where is the friction?</li><li>What deserves attention first?</li></ul></div></li><li><figure><img src="assets/images/method-connect.webp" width="1600" height="1067" loading="lazy" alt="A person organizing digital work on a laptop"></figure><div class="method-body"><span>02 · Build</span><h3>Put the Right Support Around It.</h3><p>Coordinate people, technology, business systems, and process around the agreed priorities.</p><ul><li>Preserve what works.</li><li>Improve what doesn't.</li><li>Build what's missing.</li></ul></div></li><li><figure><img src="assets/images/method-serve.webp" width="1600" height="1067" loading="lazy" alt="A café owner preparing a customer order"></figure><div class="method-body"><span>03 · Operate</span><h3>Make It Work in the Real Business.</h3><p>Put the support into operation. Observe performance, clarify ownership, and adjust as the business teaches us more.</p><ul><li>Run and measure.</li><li>Learn and adjust.</li><li>Improve over time.</li></ul></div></li></ol>''','soft')
s+=framework()
s+=section(split('Start focused','Prove What Works.<br>Expand From There.',['Where appropriate, an engagement can begin with a focused pilot around defined priorities. Everything does not need to change at once.','Agree what to improve, introduce the support, and observe how it performs. Use what happens in the real business to decide what should continue, change, or expand.','The scope, measures, responsibilities, and next steps belong in that discussion.'],'business-systems-900','A computer and business tools at a working service counter'))
s+=section(heading('You + OMG','You Know Your Business.<br>We Help You Carry More of It.')+cards([('You Bring the Context','Business knowledge, customer understanding, priorities, experience, and judgment. You remain in command.'),('We Help Bring Coordination','People, systems, process, technology, execution support, and follow-through around the agreed work.'),('We Keep Learning Together','Clear ownership, visibility into the work, and practical improvements based on what happens in operation.')]),'soft')
s+=capabilities()
s+=rhythm()
s+=nextpage(4,'The Process Should Lead<br>to a Better Working Business.','The important question is what becomes easier, clearer, or more consistent because the support is there.','See what better can look like')
write('how-it-works.html','How It Works','Understand the business, build the right support, and put it to work through Diagnose, Build, and Operate.',s)

# 05 — Outcomes and clearly labeled scenarios, never invented client evidence.
s=hero(5,'The Result Is What Changes<br>in the Business.','Work alone is not the outcome. What matters is what becomes easier, faster, clearer, more consistent, or more manageable because the right support is in place.','kitchen-team','A kitchen team preparing food together during service','See what better can look like')
s+=section(heading('Activity is not the result','The Work Is the Starting Point.<br>The Change Is What Matters.')+'<div class="outcome-path"><div>'+symbol('i-systems')+'<h3>Put support in place</h3><p>A clearer response process.</p></div><span aria-hidden="true">'+ARROW+'</span><div>'+symbol('i-flow')+'<h3>Change how work moves</h3><p>An owner and a next step.</p></div><span aria-hidden="true">'+ARROW+'</span><div>'+symbol('i-check')+'<h3>Make the business easier</h3><p>More consistent attention for customers.</p></div></div>',id='page-content')
s+=outcomes()
SCENARIO_PHOTOS=[('scenario-inquiry','A tradesperson working beside a service van'),('scenario-administration','A café team handling the work behind the counter'),('scenario-handoffs','Florists coordinating work in a busy flower shop')]
scenarios=[('Missed Customer Inquiries','Calls and inquiries arrive while the owner is working and unavailable.','A response process, clear ownership, and appropriate people and systems are organized around the inquiry.','Customers can receive more consistent responses while fewer initial inquiries require the owner.'),('Administrative Bottleneck','Recurring tasks interrupt the owner and compete with higher-value decisions.','Responsibilities are identified, documented, delegated, and supported.','Less routine work may remain trapped with the owner, creating room for other priorities.'),('Disconnected Operations','Information lives across calls, messages, inboxes, spreadsheets, and individual employees.','The workflow is mapped, responsibilities clarified, and appropriate systems and processes connected.','A clearer view of the work, fewer handoff problems, and greater operating consistency become possible.')]
s+=section(heading('From problem to change','What Improvement Could Look Like.','Illustrative scenarios, not client case studies. These describe possible applications of the approach.')+''.join(f'<article class="scenario"><div class="scenario-visual">{image(*SCENARIO_PHOTOS[i-1])}<div><p class="scenario-label">Illustrative scenario · {i:02}</p><h3>{t}</h3></div></div><div class="scenario-stages"><div><h4>The problem</h4><p>{a}</p></div><div><h4>What could change</h4><p>{b}</p></div><div><h4>Potential outcome</h4><p>{c}</p></div></div></article>' for i,(t,a,b,c) in enumerate(scenarios,1))+'<p class="editorial-note">These examples do not represent verified client outcomes or guaranteed performance. Actual solutions and results depend on the business, the agreed scope, and the evidence available.</p>')
s+=section('<div class="evidence-layout"><figure>'+image('evidence-working-floor','A team organizing work across a warehouse floor')+'</figure><div><p class="eyebrow">Proof should mean something</p><h2>Evidence before claims.<br><em>Context before numbers.</em></h2><p>Agree the starting point. Look at the change that matters to the business. Keep the context around every result.</p><div class="evidence-definitions">'+''.join(f'<details><summary>{title}</summary><p>{copy}</p></details>' for title,copy in [('Verified result','An achieved result supported by reliable client or operating evidence.'),('Observed improvement','A real change described with context, without unsupported numerical precision.'),('Illustrative scenario','An example of how the approach could work. The scenarios on this page are illustrative.'),('Target outcome','An agreed objective. It becomes a result after it has been achieved and verified.')])+'</div></div></div>','soft')

