s+=section('<div class="featured-resource">'+split('Featured guide','Where Is the Friction<br>in Your Business?',['A missed call may be a capacity problem. A capacity problem may be a process problem.','Follow one piece of work, look beyond the symptom, and find a useful place to start.'],'resources-worksite','Construction employees coordinating work on a job site',False,('guide-find-the-friction.html','Read the guide'))+'</div>')
filters=[('all','All resources'),('Time','I need more time'),('Customers','Customers need attention'),('Systems','Our tools need clarity'),('Operations','Work feels disorganized')]
