s+=section('''<div class="contact-layout"><div class="contact-aside"><p class="eyebrow">One place to start</p><h2>Tell Us What's<br>Happening.</h2><p>You don't need to have everything figured out. Share enough context to help us understand the situation.</p><p>Prefer email?<br><a href="mailto:info@onemahogany.com">info@onemahogany.com</a></p><p>This local website prepares a draft in your email app. Review and send it there when you're ready.</p></div><div><form class="conversation-form" id="conversation-form"><label for="your-name">Your name (required)</label><input id="your-name" name="name" autocomplete="name" required maxlength="120"><div class="form-grid"><div><label for="your-business">Business name</label><input id="your-business" name="business" autocomplete="organization" maxlength="160"></div><div><label for="your-email">Email (required)</label><input id="your-email" name="email" type="email" autocomplete="email" required maxlength="254"></div><div><label for="your-phone">Phone (optional)</label><input id="your-phone" name="phone" type="tel" autocomplete="tel" maxlength="40"></div><div><label for="your-website">Website (optional)</label><input id="your-website" name="website" type="url" autocomplete="url" placeholder="https://" maxlength="300"></div></div><label for="your-situation">What's happening in your business? (required)</label><textarea id="your-situation" name="message" rows="5" required maxlength="4000" placeholder="What is taking too much time, getting missed, or feeling harder than it should?"></textarea><label for="your-change">What would you like to see change? (optional)</label><textarea id="your-change" name="change" rows="3" maxlength="2000"></textarea><button class="button button-primary" type="submit">Prepare my conversation email <svg aria-hidden="true"><use href="#i-arrow"/></svg></button><p class="form-note">Nothing is sent or stored by this website. Your email app sends the message after you review it.</p></form><div class="form-confirmation" id="conversation-ready" hidden role="status"><h3 tabindex="-1" id="conversation-ready-title">Your Email Draft Is Ready.</h3><p>Open the draft in your email app, check the details, and send it when you're ready. This website has not sent your message.</p><a class="button button-primary" id="conversation-draft" href="mailto:info@onemahogany.com">Open email draft <svg aria-hidden="true"><use href="#i-arrow"/></svg></a><button class="text-link" type="button" id="conversation-edit">Edit my message</button><p>If your email app does not open, email info@onemahogany.com directly.</p></div></div></div>''','soft','conversation')
faq=[('Do I need to know which service I need?','No. Start by telling us what is happening. The conversation comes before choosing the support.'),('What if I have more than one problem?','Business problems often involve several moving parts. We can help determine what deserves attention first.'),('Do I need to prepare anything?','No formal scope or technical explanation is required. A recent example of what is getting in the way is enough to start.'),('Do I have to commit to a project?','The first conversation is about understanding the situation and whether there is a sensible next step.'),('What happens when I use this form?','The form prepares an email draft. Review and send it from your email app. The website does not submit your message to a server.')]
